router8.post(["/copy-skus/:skuId/versions", "/:skuId/versions"], async (req, res, next) => {
  try {
    const userId = toValidUuid2(req.user?.id);
    const skuId = String(req.params.skuId);
    const {
      parentVersionId,
      productDnaVersionId,
      assetVersionId,
      contentJson,
      sourceType = "manual_edit",
      generationProvider = "google",
      generationModel = "gemini-2.5-flash",
      promptSnapshot = ""
    } = req.body || {};
    let sku = null;
    let existingVersions = [];
    try {
      const { data: skuData } = await supabaseAdmin.from("copy_skus").select("*").or(`id.eq.${skuId},sku_code.eq.${skuId}`).maybeSingle();
      if (skuData) {
        sku = skuData;
        const { data: verList } = await supabaseAdmin.from("copy_versions").select("*").eq("copy_sku_id", sku.id).order("version_number", { ascending: true });
        existingVersions = verList || [];
      }
    } catch (e) {
    }
    if (!sku) {
      sku = inMemoryCopySkus.get(skuId);
      if (!sku) {
        for (const item of inMemoryCopySkus.values()) {
          if (item.sku_code === skuId) {
            sku = item;
            break;
          }
        }
      }
      if (sku) {
        existingVersions = inMemoryCopyVersions.get(sku.id) || [];
      }
    }
    if (!sku) {
      throw new AppError(`Copy SKU '${skuId}' not found`, 404);
    }
    const { valid, sanitized, errorMsg } = validateAndSanitizeCopyContent(contentJson);
    if (!valid) {
      throw new AppError(errorMsg || "Invalid Copy JSON schema", 400);
    }
    const contentHash = computeCopyContentHash(sanitized);
    return await withSkuLock(sku.id, async () => {
      let verList = inMemoryCopyVersions.get(sku.id) || [];
      try {
        const { data: latestVerList } = await supabaseAdmin.from("copy_versions").select("*").eq("copy_sku_id", sku.id).order("version_number", { ascending: true });
        if (latestVerList && latestVerList.length > 0) verList = latestVerList;
      } catch (e) {
      }
      const nextNumber = verList.length > 0 ? Math.max(...verList.map((v) => v.version_number || 0)) + 1 : 1;
      const versionCode = `COPY-V${String(nextNumber).padStart(3, "0")}`;
      let validParentId = null;
      if (nextNumber === 1) {
        validParentId = null;
      } else {
        if (!parentVersionId) {
          validParentId = sku.current_version_id || verList[verList.length - 1]?.id || null;
        } else {
          const parentMatch = verList.find((v) => v.id === parentVersionId);
          if (!parentMatch) {
            throw new AppError(`parentVersionId '${parentVersionId}' not found in SKU '${sku.sku_code}'`, 400);
          }
          validParentId = parentVersionId;
        }
      }
      const versionId = `ver_copy_${sku.sku_code}_${versionCode}_${Date.now()}`;
      const newVersion = {
        id: versionId,
        copy_sku_id: sku.id,
        version_number: nextNumber,
        version_code: versionCode,
        parent_version_id: validParentId,
        source_type: sourceType,
        product_dna_version_id: productDnaVersionId || null,
        asset_version_id: assetVersionId || null,
        content_json: sanitized,
        content_hash: contentHash,
        generation_provider: generationProvider,
        generation_model: generationModel,
        prompt_snapshot: promptSnapshot || "",
        status: "active",
        created_by: userId,
        created_at: (/* @__PURE__ */ new Date()).toISOString()
      };
      let savedToDb = false;
      try {
        const { data, error } = await supabaseAdmin.from("copy_versions").insert(newVersion).select().single();
        if (!error && data) {
          savedToDb = true;
          await supabaseAdmin.from("copy_skus").update({ current_version_id: versionId, updated_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", sku.id);
        }
      } catch (dbErr) {
        console.warn("[CopyVersions:DB] Exception inserting Copy Version in DB:", dbErr?.message);
      }
      const updatedVerList = [...verList.filter((v) => v.id !== versionId), newVersion];
      inMemoryCopyVersions.set(sku.id, updatedVerList);
      sku.current_version_id = versionId;
      sku.updated_at = (/* @__PURE__ */ new Date()).toISOString();
      inMemoryCopySkus.set(sku.id, sku);
      persistCopyStoreToDisk(sku, updatedVerList);
      return res.status(201).json({
        success: true,
        version: newVersion,
        copySku: {
          ...sku,
          current_version_id: versionId
        },
        storageMedium: savedToDb ? "supabase_db" : "in_memory"
      });
    });
  } catch (err) {
    next(err);
  }
});
router8.post(["/copy-skus/:skuId/select-version", "/:skuId/select-version"], async (req, res, next) => {
  try {
    const skuId = String(req.params.skuId);
    const { versionId } = req.body || {};
    if (!versionId) {
      throw new AppError("versionId is required", 400);
    }
    let sku = null;
    let version = null;
    try {
      const { data: skuData } = await supabaseAdmin.from("copy_skus").select("*").or(`id.eq.${skuId},sku_code.eq.${skuId}`).maybeSingle();
      if (skuData) {
        sku = skuData;
        const { data: verData } = await supabaseAdmin.from("copy_versions").select("*").eq("id", versionId).maybeSingle();
        if (verData) version = verData;
      }
    } catch (e) {
    }
    if (!sku) {
      sku = inMemoryCopySkus.get(skuId);
      if (!sku) {
        for (const item of inMemoryCopySkus.values()) {
          if (item.sku_code === skuId) {
            sku = item;
            break;
          }
        }
      }
    }
    if (!sku) {
      throw new AppError(`Copy SKU '${skuId}' not found`, 404);
    }
    if (!version) {
      for (const verList2 of inMemoryCopyVersions.values()) {
        const found = verList2.find((v) => v.id === versionId);
        if (found) {
          version = found;
          break;
        }
      }
    }
    if (!version) {
      throw new AppError(`Copy Version '${versionId}' not found`, 404);
    }
    if (version.copy_sku_id !== sku.id) {
      throw new AppError(`Copy Version '${versionId}' does not belong to Copy SKU '${sku.sku_code}'`, 400);
    }
    sku.current_version_id = versionId;
    sku.updated_at = (/* @__PURE__ */ new Date()).toISOString();
    try {
      await supabaseAdmin.from("copy_skus").update({ current_version_id: versionId, updated_at: sku.updated_at }).eq("id", sku.id);
    } catch (e) {
    }
    inMemoryCopySkus.set(sku.id, sku);
    const verList = inMemoryCopyVersions.get(sku.id) || [];
    persistCopyStoreToDisk(sku, verList);
    return res.json({
      success: true,
      copySku: sku,
      activeVersion: version
    });
  } catch (err) {
    next(err);
  }
});
