var sseClientsMap = /* @__PURE__ */ new Map();
function broadcastConsistencySSE(canvasId, eventName, data) {
  const clients = sseClientsMap.get(canvasId) || [];
  const payload = `event: ${eventName}
data: ${JSON.stringify(data)}

`;
  for (const res of clients) {
    try {
      res.write(payload);
    } catch (e) {
    }
  }
}
router10.get("/:canvasId/product-consistency/sse", (req, res) => {
  const canvasId = String(req.params.canvasId);
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders();
  const clients = sseClientsMap.get(canvasId) || [];
  clients.push(res);
  sseClientsMap.set(canvasId, clients);
  res.write(`event: connected
data: ${JSON.stringify({ canvasId, time: (/* @__PURE__ */ new Date()).toISOString() })}

`);
  req.on("close", () => {
    const list = sseClientsMap.get(canvasId) || [];
    const filtered = list.filter((c) => c !== res);
    if (filtered.length > 0) {
      sseClientsMap.set(canvasId, filtered);
    } else {
      sseClientsMap.delete(canvasId);
    }
  });
});
